class Solution {
    private boolean[][] rows = new boolean[9][9];
    private boolean[][] cols = new boolean[9][9];
    private boolean[][] boxes = new boolean[9][9];
    public void solveSudoku(char[][] board) {
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') {
                    int d = board[i][j] - '1';
                    rows[i][d] = cols[j][d] = boxes[i / 3 * 3 + j / 3][d] = true;
                }
            }
        }
        solve(board, 0, 0);
    }
    private boolean solve(char[][] board, int r, int c) {
        if (r == 9) return true;
        int nr = c == 8 ? r + 1 : r, nc = c == 8 ? 0 : c + 1;
        if (board[r][c] != '.') return solve(board, nr, nc);
        int box = r / 3 * 3 + c / 3;
        for (int d = 0; d < 9; d++) {
            if (!rows[r][d] && !cols[c][d] && !boxes[box][d]) {
                rows[r][d] = cols[c][d] = boxes[box][d] = true;
                board[r][c] = (char) ('1' + d);
                if (solve(board, nr, nc)) return true;
                rows[r][d] = cols[c][d] = boxes[box][d] = false;
                board[r][c] = '.';
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    private int[] rowMask = new int[9];
    private int[] colMask = new int[9];
    private int[] boxMask = new int[9];
    private List<int[]> emptyCells = new ArrayList<>();
    public void solveSudoku(char[][] board) {
        rowMask = new int[9];
        colMask = new int[9];
        boxMask = new int[9];
        emptyCells = new ArrayList<>();
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') {
                    int bit = 1 << (board[i][j] - '1');
                    rowMask[i] |= bit;
                    colMask[j] |= bit;
                    boxMask[i / 3 * 3 + j / 3] |= bit;
                } else {
                    emptyCells.add(new int[]{i, j});
                }
            }
        }
        solve(board, 0);
    }
    private boolean solve(char[][] board, int idx) {
        if (idx == emptyCells.size()) return true;
        int r = emptyCells.get(idx)[0];
        int c = emptyCells.get(idx)[1];
        int box = r / 3 * 3 + c / 3;
        int used = rowMask[r] | colMask[c] | boxMask[box];
        int available = ~used & 0x1FF;
        while (available != 0) {
            int bit = available & (-available);
            available &= available - 1;
            rowMask[r] |= bit;
            colMask[c] |= bit;
            boxMask[box] |= bit;
            board[r][c] = (char)('1' + Integer.numberOfTrailingZeros(bit));
            if (solve(board, idx + 1)) return true;
            rowMask[r] ^= bit;
            colMask[c] ^= bit;
            boxMask[box] ^= bit;
        }
        board[r][c] = '.';
        return false;
    }
}
